<script lang="ts">export let state:string; export let warning:string|null=null; const labels:Record<string,string>={no_rulebook:'No content yet',extracting:'Preparing…',ready_to_generate:'Ready to generate',generating:'Generating…',draft:'Needs review',published:'Ready to play',rejected:'Rejected'}; $: label=labels[state]||state; $: loading=['extracting','generating'].includes(state);</script>
<span class="badge {state}" role="status" aria-label={label}>{#if loading}<span class="spinner" aria-hidden="true"></span>{/if}{label}</span>{#if warning}<span class="warning-badge" role="status">Review extraction</span>{/if}
<style>.badge,.warning-badge{display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:3px 8px;font-size:12px}.warning-badge{color:#ffca85;background:#ffca851a}.published{color:#61ffca;background:#61ffca1a}.draft{color:#ffca85;background:#ffca851a}.rejected{color:#ff6767;background:#ff67671a}.no_rulebook,.ready_to_generate,.extracting,.generating{color:#6d6d6d}.spinner{width:10px;height:10px;border:1px solid currentColor;border-top-color:transparent;border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}</style>
